#!/usr/bin/env node
'use strict';

/**
 * Generate sitemap.xml: the static pages plus one antenna.html?id=<slug> URL per
 * public catalog entry (the same canonical URL antenna.html sets at runtime).
 *
 *   node .github/scripts/build-sitemap.js          # write sitemap.xml
 *   node .github/scripts/build-sitemap.js --check  # fail if sitemap.xml is stale
 */

const fs = require('fs');
const path = require('path');
const { SITE_ORIGIN, antennaDetailUrl } = require('../../antenna-format.js');

const root = path.join(__dirname, '..', '..');
const catalogPath = path.join(root, 'antenna_catalog.json');
const sitemapPath = path.join(root, 'sitemap.xml');

const STATIC_PAGES = ['', 'finder.html', 'compare.html', 'changes.html', 'submit.html', 'edit.html'];

function xmlEscape(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

function buildSitemap(catalog) {
  if (!Array.isArray(catalog)) throw new Error('antenna_catalog.json must be an array');
  const urls = STATIC_PAGES.map(page => `${SITE_ORIGIN}/${page}`)
    .concat(catalog.map(antennaDetailUrl));
  const seen = new Set();
  urls.forEach(url => {
    if (seen.has(url)) throw new Error('duplicate sitemap URL ' + url);
    seen.add(url);
  });
  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<!-- Generated by .github/scripts/build-sitemap.js (npm run build). Do not edit. -->',
    '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">',
    ...urls.map(url => `  <url><loc>${xmlEscape(url)}</loc></url>`),
    '</urlset>',
    ''
  ].join('\n');
}

function main() {
  const catalog = JSON.parse(fs.readFileSync(catalogPath, 'utf8'));
  const xml = buildSitemap(catalog);
  const count = xml.split('<url>').length - 1;
  if (process.argv.includes('--check')) {
    const current = fs.existsSync(sitemapPath) ? fs.readFileSync(sitemapPath, 'utf8') : '';
    if (current !== xml) {
      console.error('sitemap.xml is stale. Run: npm run build');
      process.exit(1);
    }
    console.log('OK: sitemap.xml matches the catalog (' + count + ' URLs)');
    return;
  }
  fs.writeFileSync(sitemapPath, xml);
  console.log('Wrote sitemap.xml (' + count + ' URLs)');
}

if (require.main === module) main();

module.exports = { buildSitemap };
